// Brasília 120 — leitor editorial, sem dependências em tempo de execução.
function el(id) {
    const node = document.getElementById(id);
    if (!node)
        throw new Error(`Elemento ausente: ${id}`);
    return node;
}
const book = el('book');
const reader = el('reader');
let pageImage = el('page');
const turn = el('turn');
const turnImg = el('turn-img');
const shade = el('turn-shade');
const prev = el('prev');
const next = el('next');
const range = el('progress');
const focusButton = el('focus');
const indexDialog = el('index-dialog');
const zoomDialog = el('zoom-dialog');
const textDialog = el('text-dialog');
const reduced = matchMedia('(prefers-reduced-motion: reduce)');
const chapterButtons = [...document.querySelectorAll('[data-page]')];
const TOTAL = PAGES.length;
const pad = (n) => String(n).padStart(2, '0');
const clamp = (n, a, b) => Math.min(b, Math.max(a, n));
const valid = (n) => n >= 1 && n <= TOTAL;
const asset = (n, size) => `pages/${pad(n)}-${size}.png`;
const chapterName = (n) => n === 1 ? 'Capa' : n < 7 ? 'Abertura' : n < 19 ? 'I — Monumental' : n < 35 ? 'II — Flâneur' : n < 54 ? 'III — Sociopolítica' : n === TOTAL ? 'Contracapa' : 'Encerramento';
const pageAlt = (n) => `Página ${n} de ${TOTAL}: ${PAGES[n - 1].title}`;
let current = 1;
let busy = false;
let preview = null;
let gesture = null;
const cache = new Map();
function loadPage(n) {
    const cached = cache.get(n);
    if (cached)
        return cached;
    const img = new Image();
    img.id = 'page';
    img.className = 'page-image';
    img.alt = pageAlt(n);
    img.width = 2400;
    img.height = 2400;
    img.draggable = false;
    img.decoding = 'async';
    const promise = new Promise((resolve, reject) => {
        img.onload = () => { img.decode().catch(() => { }).then(() => resolve(img)); };
        img.onerror = () => { cache.delete(n); reject(new Error(`Página ${n} indisponível`)); };
        img.src = asset(n, 'large');
    });
    cache.set(n, promise);
    return promise;
}
function prefetch() {
    // Somente páginas próximas; mantém o consumo de memória previsível.
    for (const n of cache.keys())
        if (Math.abs(n - current) > 1)
            cache.delete(n);
    for (const n of [current + 1, current - 1])
        if (valid(n))
            void loadPage(n).catch(() => { });
}
function sync(announce = false) {
    el('current').textContent = pad(current);
    el('total').textContent = pad(TOTAL);
    el('chapter').textContent = chapterName(current);
    prev.disabled = busy || current === 1;
    next.disabled = busy || current === TOTAL;
    range.value = String(current);
    range.max = String(TOTAL);
    range.style.setProperty('--progress', `${(current - 1) / (TOTAL - 1) * 100}%`);
    range.setAttribute('aria-valuetext', `Página ${current} de ${TOTAL}`);
    chapterButtons.forEach(b => b.setAttribute('aria-current', String(Number(b.dataset.page) === (current >= 35 && current < 54 ? 35 : current >= 19 && current < 35 ? 19 : current >= 7 && current < 19 ? 7 : 0))));
    document.querySelectorAll('.thumb').forEach(b => b.setAttribute('aria-current', String(Number(b.dataset.number) === current)));
    el('read-text').disabled = !PAGES[current - 1].text.trim();
    if (announce)
        el('announce').textContent = pageAlt(current);
}
function replaceBase(img) { if (img !== pageImage) {
    pageImage.replaceWith(img);
    pageImage = img;
} }
function renderTurn(p) {
    if (!preview)
        return;
    p = clamp(p, 0, 1);
    preview.progress = p;
    // A folha frontal gira em torno da lombada virtual, revelando a próxima.
    turn.style.transformOrigin = preview.direction > 0 ? 'left center' : 'right center';
    turn.style.transform = `rotateY(${preview.direction * -p * 89.5}deg)`;
    turn.style.opacity = String(p > .85 ? (1 - p) / .15 : 1);
    shade.style.background = preview.direction > 0 ? 'linear-gradient(90deg,#0000 12%,#000d 100%)' : 'linear-gradient(270deg,#0000 12%,#000d 100%)';
    shade.style.opacity = String(p * .76);
}
function beginPreview(target, img) {
    if (preview)
        return;
    const original = pageImage;
    turnImg.src = original.currentSrc || original.src;
    preview = { target, direction: Math.sign(target - current), original, progress: 0 };
    renderTurn(0);
    turn.hidden = false;
    replaceBase(img);
}
function closePreview(commit) {
    if (!preview)
        return;
    if (commit)
        current = preview.target;
    else
        replaceBase(preview.original);
    turn.hidden = true;
    turnImg.removeAttribute('src');
    preview = null;
}
function animateTo(end, duration) {
    if (!preview || reduced.matches || duration <= 0) {
        renderTurn(end);
        return Promise.resolve();
    }
    const from = preview.progress;
    return new Promise(resolve => {
        const start = performance.now();
        const tick = (now) => {
            const t = clamp((now - start) / duration, 0, 1);
            const eased = 1 - Math.pow(1 - t, 3);
            renderTurn(from + (end - from) * eased);
            if (t < 1)
                requestAnimationFrame(tick);
            else
                resolve();
        };
        requestAnimationFrame(tick);
    });
}
async function go(target, animated = true) {
    target = clamp(Math.round(target), 1, TOTAL);
    if (busy || gesture || target === current) {
        sync();
        return;
    }
    busy = true;
    sync();
    el('error').hidden = true;
    const timer = window.setTimeout(() => { el('loading').hidden = false; }, 180);
    try {
        if (preview && preview.target !== target)
            closePreview(false);
        if (!preview) {
            const img = await loadPage(target);
            beginPreview(target, img);
        }
        await animateTo(1, animated ? Math.max(160, 460 * (1 - (preview?.progress ?? 0))) : 0);
        closePreview(true);
    }
    catch {
        closePreview(false);
        el('error').hidden = false;
    }
    finally {
        clearTimeout(timer);
        el('loading').hidden = true;
        busy = false;
        sync(true);
        prefetch();
    }
}
async function revert() {
    if (!preview)
        return;
    busy = true;
    sync();
    await animateTo(0, 190);
    closePreview(false);
    busy = false;
    sync();
}
function showReader() { if (document.body.classList.contains('immersive'))
    return; reader.scrollIntoView({ behavior: reduced.matches ? 'instant' : 'smooth', block: 'start' }); reader.focus({ preventScroll: true }); }
prev.addEventListener('click', () => void go(current - 1));
next.addEventListener('click', () => void go(current + 1));
el('start').addEventListener('click', showReader);
chapterButtons.forEach(b => b.addEventListener('click', () => { showReader(); void go(Number(b.dataset.page)); }));
range.addEventListener('input', () => { range.setAttribute('aria-valuetext', `Ir à página ${range.value}`); range.style.setProperty('--progress', `${(Number(range.value) - 1) / (TOTAL - 1) * 100}%`); });
